// CloudIT Operations Portal — Phase 11 incident evidence publisher.
//
// Maps sanitized rows of the n8n Data Table "cavetta_maintenance_events"
// (written by the "Cavetta - Incident Monitor" workflow) into 'incident'
// envelopes for the shared "CloudIT - Publish Operations Evidence"
// sub-workflow (operations_ingest.insert_incident, migration 0005).
//
// IMPORT BINDING: the "Load Maintenance Events" Data Table node is exported
// with an EMPTY dataTableId value that MUST be re-bound to the
// "cavetta_maintenance_events" table on import (list mode keeps the cached
// name "cavetta_maintenance_events"). Same convention as the Execute
// Workflow "Publish Evidence" node, whose workflowId is bound on import.
//
// Sanitization (safe_text strips URLs): safeSummary is built ONLY from the
// fixed monitor name and the derived failure category — never from the row
// URL or the raw detail text. The monitor map is FIXED here, mirroring the
// Incident Monitor's approvedMonitors: monitor 4 (Cavetta Home Contacts)
// has NO registered operations endpoint (migration 0006 seed), so its
// records omit endpointKey entirely — an unregistered endpointKey rejects
// the WHOLE batch (endpoint_not_registered).
//
// REJECTED_MONITOR_EVENT rows and unknown alert types (including Uptime
// Kuma TEST heartbeats) are skipped entirely so a stray row can never
// reject the batch. Records are sorted by eventAt ascending: chronological
// application must leave the correct FINAL state when one window holds
// both a DOWN and an UP for the same monitor.
//
// incidentKey is stable per monitor (repeated downtimes upsert ONE
// incident row and add occurrence_count); idempotencyKey is stable per
// source event (replays dedupe to 'duplicate' and never re-increment).
//
// All timestamps are computed at RUN TIME — never hardcode a test clock:
// publishedAt must be within +/-5 minutes of ingestion (0004
// stale_timestamp).

const WINDOW_MS = 48 * 60 * 60 * 1000; // eventAt lookback window
const FRESH_MS = 24 * 60 * 60 * 1000; // freshUntil = now + 24h

// Fixed monitor map: mirror of the Incident Monitor's approvedMonitors,
// extended with the operations endpoint key (null = not registered).
const MONITORS = {
  1: { name: 'Cavetta Home', endpointKey: 'cavetta.website' },
  2: { name: 'Cavetta Home Properties', endpointKey: 'cavetta.listings' },
  3: { name: 'Cavetta Home Sitemap', endpointKey: 'cavetta.sitemap' },
  4: { name: 'Cavetta Home Contacts', endpointKey: null },
  5: { name: 'Cavetta Home Robot', endpointKey: 'cavetta.robots' }
};

function sanitizeKeyPart(value) {
  // idempotencyKey charset guard: keep only [a-zA-Z0-9_.-]
  return String(value ?? '').replace(/[^a-zA-Z0-9_.-]/g, '');
}

function deriveFailureCategory(detail) {
  const d = String(detail ?? '').toLowerCase();
  if (d.includes('http 5')) return 'http_5xx';
  if (d.includes('http 4')) return 'http_4xx';
  if (d.includes('enotfound') || d.includes('dns')) return 'dns';
  if (d.includes('etimedout') || d.includes('timeout') || d.includes('timed out')) return 'timeout';
  if (d.includes('cert') || d.includes('tls') || d.includes('ssl')) return 'tls';
  return 'unknown_sanitized';
}

function mapEvents(events, now) {
  const publishedAt = now.toISOString();
  const freshUntil = new Date(now.getTime() + FRESH_MS).toISOString();
  const nowMs = now.getTime();
  const records = [];

  for (const event of events) {
    const alertType = String(event?.alertType ?? '');
    const monitorId = Number(event?.monitorId);
    const monitor = MONITORS[monitorId];

    // REJECTED_MONITOR_EVENT rows are audit noise from the incident monitor
    // and never reach the operations portal.
    if (alertType === 'REJECTED_MONITOR_EVENT') continue;
    // Unknown monitors and unknown alert types (incl. Uptime Kuma TEST
    // heartbeats) are skipped defensively.
    if (!monitor) continue;
    if (
      alertType !== 'CONFIRMED_DOWN' &&
      alertType !== 'RECOVERED' &&
      alertType !== 'RECOVERED_DURING_CONFIRMATION'
    ) {
      continue;
    }

    const eventAt = String(event?.eventAt ?? '');
    const eventAtMs = Date.parse(eventAt);
    if (!eventAt || Number.isNaN(eventAtMs)) continue;
    if (nowMs - eventAtMs > WINDOW_MS) continue; // outside the 48h lookback

    const checkedAtRaw = String(event?.checkedAt ?? '');
    const checkedAt = !Number.isNaN(Date.parse(checkedAtRaw)) ? checkedAtRaw : eventAt;

    const incidentKey = 'cavetta-uptime-' + monitorId;
    const idempotencyKey =
      'incident-cavetta-uptime-' + monitorId + '-' + alertType + '-' +
      sanitizeKeyPart(eventAt);

    let record;
    if (alertType === 'CONFIRMED_DOWN') {
      const failureCategory = deriveFailureCategory(event?.detail);
      record = {
        contractVersion: '1.0',
        recordType: 'incident',
        idempotencyKey,
        environmentKey: 'production',
        sourceSystem: 'n8n',
        observedAt: publishedAt,
        publishedAt,
        freshUntil,
        status: 'RED',
        severity: 'critical',
        correlationKey: null,
        payload: {
          incidentKey,
          serviceKey: incidentKey,
          state: 'open',
          severity: 'critical',
          failureCategory,
          startedAt: eventAt,
          confirmedAt: checkedAt,
          occurrenceCount: 1,
          safeSummary: (monitor.name + ' confirmed down (' + failureCategory + ')').slice(0, 300),
          safeAction: 'Manual investigation required'
        }
      };
    } else if (alertType === 'RECOVERED') {
      record = {
        contractVersion: '1.0',
        recordType: 'incident',
        idempotencyKey,
        environmentKey: 'production',
        sourceSystem: 'n8n',
        observedAt: publishedAt,
        publishedAt,
        freshUntil,
        status: 'GREEN',
        severity: 'info',
        correlationKey: null,
        payload: {
          incidentKey,
          serviceKey: incidentKey,
          state: 'recovered',
          severity: 'info',
          // startedAt is REQUIRED by insert_incident (migration 0005); a
          // bare recovery without a prior DOWN seeds it from eventAt.
          // occurrenceCount must be within the DB CHECK range 1..100000, so
          // recoveries send 1; the upsert counts events (occurrence_count
          // therefore includes recoveries — a known, accepted semantic).
          startedAt: eventAt,
          recoveredAt: eventAt,
          occurrenceCount: 1,
          safeSummary: monitor.name + ' recovered',
          safeAction: 'None'
        }
      };
    } else {
      // RECOVERED_DURING_CONFIRMATION
      const failureCategory = deriveFailureCategory(event?.detail);
      record = {
        contractVersion: '1.0',
        recordType: 'incident',
        idempotencyKey,
        environmentKey: 'production',
        sourceSystem: 'n8n',
        observedAt: publishedAt,
        publishedAt,
        freshUntil,
        status: 'GREEN',
        severity: 'info',
        correlationKey: null,
        payload: {
          incidentKey,
          serviceKey: incidentKey,
          state: 'recovered',
          severity: 'info',
          failureCategory,
          startedAt: eventAt,
          recoveredAt: checkedAt,
          occurrenceCount: 1,
          safeSummary: (monitor.name + ' recovered during confirmation (' + failureCategory + ')').slice(0, 300),
          safeAction: 'None'
        }
      };
    }

    // Monitor 4 has no registered endpoint: omit the key entirely rather
    // than send an unregistered one.
    if (monitor.endpointKey) {
      record.payload.endpointKey = monitor.endpointKey;
    }

    records.push(record);
  }

  // Chronological application: when a window holds both a DOWN and an UP
  // for the same monitor, the later event must apply LAST so the upserted
  // incident ends in the correct final state.
  records.sort((a, b) => {
    const ta = a.payload.startedAt ?? a.payload.recoveredAt ?? '';
    const tb = b.payload.startedAt ?? b.payload.recoveredAt ?? '';
    return ta < tb ? -1 : ta > tb ? 1 : 0;
  });

  return { records, publisherKey: 'cavetta-production-n8n' };
}

return mapEvents($input.all().map((item) => item.json), new Date());

// Fails LOUDLY (a descriptive Error, visible in the n8n run, no secrets)
// instead of letting the ingest service reject the batch with a cryptic
// 422 — same style as the endpoint collector's Validate Records.
//
// Checks every envelope against the parse_envelope rules (migration 0004)
// and every payload against the strict insert_incident allowlist
// (migration 0005): an unknown payload key rejects the WHOLE batch with
// unknown_field, so any offending key is listed here before publishing.
//
// An empty records array is VALID: it is flagged with "skipped" so the
// "Has Records?" IF node routes to the no-op "Nothing To Publish" node
// instead of publishing an empty batch to the ingest service.

const batch = $json;
const records = Array.isArray(batch?.records) ? batch.records : null;

if (records === null) {
  throw new Error('Validate Records: "records" is missing or not an array');
}

if (records.length === 0) {
  return { ...batch, skipped: true };
}

const ENVELOPE_REQUIRED = ['contractVersion', 'recordType', 'idempotencyKey', 'environmentKey', 'sourceSystem', 'observedAt', 'publishedAt', 'freshUntil', 'status', 'severity', 'payload'];
const ENVELOPE_TIMES = ['observedAt', 'publishedAt', 'freshUntil'];
const PAYLOAD_ALLOWED = ['incidentKey', 'serviceKey', 'endpointKey', 'state', 'severity', 'failureCategory', 'startedAt', 'confirmedAt', 'recoveredAt', 'resolvedAt', 'occurrenceCount', 'safeSummary', 'safeAction'];
const PAYLOAD_REQUIRED = ['incidentKey', 'serviceKey', 'state', 'severity', 'startedAt'];
const PAYLOAD_TIMES = ['startedAt', 'confirmedAt', 'recoveredAt', 'resolvedAt'];
const STATUSES = ['GREEN', 'AMBER', 'RED', 'NO_DATA', 'UNKNOWN'];
const SEVERITIES = ['info', 'warning', 'critical', 'none'];
const STATES = ['open', 'recovered', 'resolved'];
const CATEGORIES = ['timeout', 'dns', 'tls', 'http_4xx', 'http_5xx', 'authentication', 'authorization', 'rate_limit', 'quota', 'provider_unavailable', 'invalid_response', 'missing_evidence', 'overdue', 'stuck_send', 'unknown_sanitized'];

for (let i = 0; i < records.length; i++) {
  const r = records[i];
  const tag = 'Validate Records: record ' + i + ' (' + (r?.payload?.incidentKey) + ')';
  if (typeof r !== 'object' || r === null) {
    throw new Error(tag + ' is not an object');
  }
  for (const k of ENVELOPE_REQUIRED) {
    if (r[k] === undefined || r[k] === null) {
      throw new Error(tag + ' is missing envelope field "' + k + '"');
    }
  }
  if (r.correlationKey === undefined) {
    throw new Error(tag + ' is missing envelope field "correlationKey"');
  }
  if (r.contractVersion !== '1.0') {
    throw new Error(tag + ' has contractVersion "' + r.contractVersion + '" (expected 1.0)');
  }
  if (r.recordType !== 'incident') {
    throw new Error(tag + ' has recordType "' + r.recordType + '" (expected incident)');
  }
  if (r.environmentKey !== 'production') {
    throw new Error(tag + ' has environmentKey "' + r.environmentKey + '" (expected production)');
  }
  if (r.sourceSystem !== 'n8n') {
    throw new Error(tag + ' has sourceSystem "' + r.sourceSystem + '" (expected n8n)');
  }
  if (!STATUSES.includes(r.status)) {
    throw new Error(tag + ' has invalid status "' + r.status + '"');
  }
  if (!SEVERITIES.includes(r.severity)) {
    throw new Error(tag + ' has invalid severity "' + r.severity + '"');
  }
  if (typeof r.idempotencyKey !== 'string' || r.idempotencyKey.length === 0) {
    throw new Error(tag + ' has an empty or non-string idempotencyKey');
  }
  if (r.idempotencyKey.length > 160 || r.idempotencyKey.includes('@') || r.idempotencyKey.includes('://')) {
    throw new Error(tag + ' has an illegal idempotencyKey "' + r.idempotencyKey + '"');
  }
  for (const k of ENVELOPE_TIMES) {
    if (Number.isNaN(Date.parse(r[k]))) {
      throw new Error(tag + ' has a non-ISO envelope timestamp "' + k + '": ' + r[k]);
    }
  }
  if (typeof r.payload !== 'object' || r.payload === null) {
    throw new Error(tag + ' has no payload object');
  }
  if (
    r.payload.occurrenceCount !== undefined &&
    r.payload.occurrenceCount !== null &&
    (!Number.isInteger(r.payload.occurrenceCount) ||
      r.payload.occurrenceCount < 1 ||
      r.payload.occurrenceCount > 100000)
  ) {
    throw new Error(tag + ' has occurrenceCount outside 1..100000: ' + r.payload.occurrenceCount);
  }
  const offending = Object.keys(r.payload).filter((k) => !PAYLOAD_ALLOWED.includes(k));
  if (offending.length > 0) {
    throw new Error(tag + ' has payload keys outside the insert_incident allowlist: ' + offending.join(', '));
  }
  for (const k of PAYLOAD_REQUIRED) {
    if (r.payload[k] === undefined || r.payload[k] === null) {
      throw new Error(tag + ' is missing required payload field "' + k + '"');
    }
  }
  if (!STATES.includes(r.payload.state)) {
    throw new Error(tag + ' has invalid payload state "' + r.payload.state + '"');
  }
  if (!SEVERITIES.includes(r.payload.severity)) {
    throw new Error(tag + ' has invalid payload severity "' + r.payload.severity + '"');
  }
  if (r.payload.failureCategory !== undefined && r.payload.failureCategory !== null && !CATEGORIES.includes(r.payload.failureCategory)) {
    throw new Error(tag + ' has invalid failureCategory "' + r.payload.failureCategory + '"');
  }
  if (!Number.isInteger(r.payload.occurrenceCount) || r.payload.occurrenceCount < 0 || r.payload.occurrenceCount > 100000) {
    throw new Error(tag + ' has an invalid occurrenceCount ' + r.payload.occurrenceCount);
  }
  for (const k of PAYLOAD_TIMES) {
    const v = r.payload[k];
    if (v !== undefined && v !== null && Number.isNaN(Date.parse(v))) {
      throw new Error(tag + ' has a non-ISO payload timestamp "' + k + '": ' + v);
    }
  }
  // URL leak guard: safe_text strips URLs upstream, so a URL here means the
  // mapping is broken — fail before it reaches the portal.
  if (typeof r.payload.safeSummary !== 'string' || r.payload.safeSummary.length > 500 || r.payload.safeSummary.includes('://')) {
    throw new Error(tag + ' has an invalid or URL-bearing safeSummary');
  }
  if (typeof r.payload.safeAction !== 'string' || r.payload.safeAction.length > 300 || r.payload.safeAction.includes('://')) {
    throw new Error(tag + ' has an invalid or URL-bearing safeAction');
  }
}

return batch;

// Quiet no-op for lookback windows with no publishable maintenance events.
// Returns a small summary object so the run log shows exactly why nothing
// was sent to the operations portal.
return {
  skipped: true,
  recordCount: 0,
  reason: 'No publishable maintenance events in the 48-hour lookback window'
};
